from layout import render_column


def test_alignment():
    assert render_column("OK", 5) == "   OK"


def test_unchanged_width():
    assert render_column("HELLO", 5) == "HELLO"

def aligns(value, width):
    return value.rjust(width)


def render_column(value, width):
    """Right-align a value for tabular output."""
    return align(value, width)
